(() => {
  const image = "data:image/png;base64,";
  class VsrCounterfactual extends HTMLElement {
    connectedCallback() {
      if (this.dataset.ready) return;
      this.dataset.ready = '1';
      this.innerHTML = '<figure><img src="' + image + '" alt="Severe RSV in Brazil by age group: observed series, counterfactual, and predictive interval since 2024."></figure>';
    }
  }
  if (!customElements.get('delta-vsr-counterfactual'))
    customElements.define('delta-vsr-counterfactual', VsrCounterfactual);
})();
